package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                      // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.New(0, 0) // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.New(0, 0)    // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0                             // PIC 9(5) len=5 = 0
var WsPrinEd string                               // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string                                // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string                              // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec

var inputDone bool

// file handling
var loanLines []string
var loanIdx int
var loanEOF bool

func isInputDone() bool { return inputDone }

func storeTruncate(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep low-order digits that fit: modulus 10^(intDigits+scale)
	totalDigits := intDigits + int(scale)
	// 10^totalDigits
	modulus := decimal.NewFromInt(1).Shift(int32(totalDigits))
	// val is already at correct scale (rounded/truncated). Get scaled integer
	// Use Shift to avoid Div
	scaled := val.Shift(scale) // val * 10^scale
	// For positive values simple mod; for safety use Abs mod and re-apply sign
	neg := scaled.IsNegative()
	absScaled := scaled.Abs()
	// decimal.Mod not exists with decimal.Decimal? shopspring has Mod
	modded := absScaled.Mod(modulus)
	if neg {
		modded = modded.Neg()
	}
	return modded.Shift(-scale)
}

func formatEdited(val decimal.Decimal, picture string) string {
	// Determine scale = number of '9' after '.'
	dotPos := strings.Index(picture, ".")
	scale := 0
	intPic := picture
	fracPic := ""
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
		// count 9's in fracPic (should be all 9)
		for _, c := range fracPic {
			if c == '9' {
				scale++
			}
		}
	}
	// count integer digit placeholders
	intCap := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intCap++
		}
	}
	absVal := val.Abs()
	// Get fixed string with required scale
	var intStr, fracStr string
	if scale > 0 {
		s := absVal.StringFixed(int32(scale))
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
		// ensure fracStr length scale
		if len(fracStr) < scale {
			fracStr += strings.Repeat("0", scale-len(fracStr))
		} else if len(fracStr) > scale {
			fracStr = fracStr[:scale]
		}
	} else {
		// no decimal
		intStr = absVal.Truncate(0).StringFixed(0)
		// string Fixed may contain sign?
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		if strings.HasPrefix(intStr, "+") {
			intStr = intStr[1:]
		}
		fracStr = ""
	}
	// handle sign removal already done via Abs
	// drop high-order digits
	if len(intStr) > intCap {
		intStr = intStr[len(intStr)-intCap:]
	}
	if len(intStr) < intCap {
		intStr = strings.Repeat("0", intCap-len(intStr)) + intStr
	}
	// first non-zero index
	firstNZ := intCap - 1 // default last position
	for i := 0; i < intCap; i++ {
		if intStr[i] != '0' {
			firstNZ = i
			break
		}
	}
	// if all zero, firstNZ stays at last index (so we show 0 at mandatory 9)
	// Build output
	out := make([]rune, len(picture))
	digitIdx := 0
	fracIdx := 0
	for i, ch := range picture {
		switch ch {
		case 'Z':
			d := rune(intStr[digitIdx])
			digitIdx++
			if digitIdx-1 < firstNZ {
				out[i] = ' '
			} else {
				out[i] = d
			}
		case '9':
			// Determine if this 9 is in integer part or fractional part
			if dotPos >= 0 && i > dotPos {
				// fractional
				if fracIdx < len(fracStr) {
					out[i] = rune(fracStr[fracIdx])
					fracIdx++
				} else {
					out[i] = '0'
				}
			} else {
				d := rune(intStr[digitIdx])
				digitIdx++
				out[i] = d
			}
		case ',':
			// visible if first non-zero digit has already been consumed (to the left)
			// last digit left of comma is digitIdx-1
			if firstNZ <= digitIdx-1 {
				out[i] = ','
			} else {
				out[i] = ' '
			}
		case '.':
			out[i] = '.'
		default:
			out[i] = ch
		}
	}
	return string(out)
}

func parseLoanLine(line string) LoanRec {
	// pad/truncate to 21
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	acct := line[0:6]
	prinStr := line[6:15]
	rateStr := line[15:19]
	yearsStr := line[19:21]

	var r LoanRec
	r.LrAcct = acct

	prinStrTrim := strings.TrimSpace(prinStr)
	if prinStrTrim == "" {
		r.LrPrincipal = decimal.New(0, 0)
	} else {
		// remove any spaces inside? Should be digits
		// but keep only digits/sign
		pr := strings.TrimSpace(prinStr)
		// COBOL numeric DISPLAY fields are digits only, if spaces treat as 0
		var iv int64
		fmt.Sscanf(pr, "%d", &iv)
		// Fallback manual parse if Sscanf fails due to leading zeros
		if pr != "" {
			// try parse with decimal
			// Use manual int parse
			var v int64 = 0
			for _, c := range pr {
				if c >= '0' && c <= '9' {
					v = v*10 + int64(c-'0')
				}
			}
			iv = v
			// detect if original string was all digits but Sscanf already ok
		}
		r.LrPrincipal = decimal.New(iv, -2)
	}

	rateStrTrim := strings.TrimSpace(rateStr)
	if rateStrTrim == "" {
		r.LrRate = decimal.New(0, 0)
	} else {
		var v int64 = 0
		for _, c := range rateStr {
			if c >= '0' && c <= '9' {
				v = v*10 + int64(c-'0')
			}
		}
		r.LrRate = decimal.New(v, -2)
	}

	yearsStrTrim := strings.TrimSpace(yearsStr)
	if yearsStrTrim == "" {
		r.LrYears = 0
	} else {
		var v int64 = 0
		for _, c := range yearsStr {
			if c >= '0' && c <= '9' {
				v = v*10 + int64(c-'0')
			}
		}
		r.LrYears = v
	}
	return r
}

// paragraphs

func ReadPara() {
	if loanIdx >= len(loanLines) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := loanLines[loanIdx]
	loanIdx++
	loanRec = parseLoanLine(line)
}

func ProcessPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	// Use precise decimal: multiply before dividing, use Shift for /100
	raw := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears)).Shift(-2)
	rounded := raw.Round(2)
	// store with truncation (low-order digits)
	WsInterest = storeTruncate(rounded, 9, 2)

	// ADD WS-INTEREST TO WS-TOTAL with size handling
	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = storeTruncate(WsTotal, 11, 2)

	// ADD 1 TO WS-COUNT with truncation 5 digits
	WsCount = WsCount + 1
	if WsCount > 99999 {
		WsCount = WsCount % 100000
	}

	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	// LR-ACCT is PIC X(6) -> exactly 6 chars
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	// PERFORM READ-PARA
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "RECORDS: " WS-COUNT  -> WS-COUNT is PIC 9(5) zero-padded
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func MainPara() {
	// OPEN INPUT LOAN-FILE
	// read file input.dat
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// if file not found, treat as empty
		loanLines = []string{}
	} else {
		// Split by lines: COBOL LINE SEQUENTIAL: one record per line
		// Use scanner to handle both \n and \r\n
		content := string(data)
		// If file is empty, no lines
		if len(content) > 0 {
			scanner := bufio.NewScanner(strings.NewReader(content))
			// allow long lines
			buf := make([]byte, 0, 64*1024)
			scanner.Buffer(buf, 1024*1024)
			for scanner.Scan() {
				line := scanner.Text()
				// Scanner strips \r and \n, but we need to preserve content without newline
				loanLines = append(loanLines, line)
			}
			// Note: if file ends without newline, scanner still returns last line
		}
	}
	loanIdx = 0
	inputDone = false
	WsEofFlag = "N"

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE LOAN-FILE (no action)
	SummaryPara()
}

func main() {
	MainPara()
}
